/**
 * The first paint of the home page is static HTML (the hero, written into index.html at build time by the heroShell plugin in
 * vite.config.ts, generated by scripts/gen-hero-shell.mjs). The app replaces it as soon as it has started. This file runs before that, so it
 * can see the static page: which picture the browser chose for the hero, so the app asks for the very same file and nothing blinks.
 */
const root = typeof document !== 'undefined' ? document.getElementById('root') : null
const poster = root?.querySelector<HTMLImageElement>('img[data-pre-poster]') ?? null

export const preShell = {
  /** True when the page arrived with the static hero in it. */
  present: !!root?.hasAttribute('data-pre') && !!poster,
  /** The picture file the browser chose for the hero (empty when there is no static hero). */
  poster: poster?.currentSrc || poster?.src || '',
}

/**
 * Resolves once the static hero picture has been decoded and a frame has been painted (or after `limit` ms, or at once when there is no static
 * hero). The app starts after this, so the first screen is on the glass before the app's script spends any time, and the picture the reader
 * sees first is the one that stays the largest contentful paint instead of being swapped for a new element a moment later.
 */
export function afterFirstPaint(limit = 1200): Promise<void> {
  if (!preShell.present || !poster) return Promise.resolve()
  return new Promise((done) => {
    let over = false
    const finish = () => { if (over) return; over = true; requestAnimationFrame(() => setTimeout(done, 0)) }
    setTimeout(finish, limit)
    poster.decode().then(finish, finish)
  })
}
if (preShell.present) document.documentElement.dataset.pre = '1'
